DYNAMIC_SOURCE_SUFFIX = '__global'
GNG_PLATFORM_TYPE_ROBOT_VARIABLE_NAME = 'GNB_PLATFORM_TYPE'
VRAN_DU_IP = '192.168.2.124'


@six.add_metaclass(Singleton)
class TestEnv(object):
    """
    Responsibility of TestEnv is to realize what type of environment library is operating with.
    Next, based on that knowledge it configures env-dependent parts of library to use proper variants of plugins.
    Main plugins for messaging are message-sources.
    """

    def __init__(self):
        self.logger = logging.getLogger('messaging.testenv')
        self.ne_factory = NetworkElementFactory()
        self.ne_validator = NetworkElementValidator()
        self.msg_src_id_factory = MsgSourceIdentificationFactory()
        self._register_available_message_sources()
        self.load_plugins()

    def _get_robot_variable(self, var_name, default=None):
        var_name = "${" + str(var_name) + "}"
        return BuiltIn().get_variable_value(var_name, default)

    def get_vran_ip(self, ip_type='cu'):
        availbale_ip_types = ['cu', 'du']
        assert ip_type in availbale_ip_types, 'ip type: {} not allowed, only {} implemented'\
            .format(ip_type, availbale_ip_types)
        ip_type_to_struct_mapping = {
            'cu': {'struct_name': '_vcu_k8s_connection_details', 'ip_field_name': 'ip_addr'},
            'du': {'struct_name': '_vdu_k8s_ssh_connection_details', 'ip_field_name': 'addr'}
        }
        tl_dir_name = socket.gethostname().replace("-", "_")
        testline_repository_path = "/home/ute/testline_configuration"
        tl_config_path = os.path.join(testline_repository_path, tl_dir_name)

        if not os.path.exists(testline_repository_path):
            raise Exception("Testline configuration repository '{}' not found".format(testline_repository_path))
        if not os.path.exists(tl_config_path):
            raise Exception("TL config file '{}' not found".format(tl_config_path))
        try:
            sys.path.append(testline_repository_path)
            # importlib is used because module name 'tl_dir_name' starts with numbers, e.g: 7_7_CLOUD5G...
            init_py_tl_variables = importlib.import_module(tl_dir_name)
            if not hasattr(init_py_tl_variables, ip_type_to_struct_mapping[ip_type]['struct_name']):
                raise Exception("'{}' not found in TL config: {}"
                                .format(ip_type_to_struct_mapping[ip_type]['struct_name'], tl_config_path))
            sub_struct = getattr(init_py_tl_variables, ip_type_to_struct_mapping[ip_type]['struct_name'])
            ip = getattr(sub_struct, ip_type_to_struct_mapping[ip_type]['ip_field_name'])
        finally:
            sys.path.remove(testline_repository_path)

        print("VRAN {} IP: {}".format(ip_type, ip))
        return ip

    def is_vran_testline(self):
        try:
            du_ip = self.get_vran_ip(ip_type='du')
        except Exception:
            print('Could not get VRAN DU ip, not a vran testline')
            return False
        print('Successfully fetched vran du ip: {}'.format(du_ip))
        vran_ping_du_command = 'ping -c 1 -w2 {} > /dev/null 2>&1'.format(du_ip)
        print('Trying to ping VRAN DU address: {}'.format(du_ip))
        vran_du_pinged_successfully = True if os.system(vran_ping_du_command) == 0 else False
        print('Vran DU {} ping : {}'.format(du_ip, 'successfull' if vran_du_pinged_successfully is True else 'failed'))
        return True if vran_du_pinged_successfully else False

    def get_gnb_platform_type(self, user=None, password=None, ip=None):
        """
        Determines gNB platform via:
        - VRAN DU ping
        - or classical gNB SSH command
        """
        platform_type_provided_via_robot = self._get_robot_variable(GNG_PLATFORM_TYPE_ROBOT_VARIABLE_NAME)
        if platform_type_provided_via_robot is not None:
            platform = platform_type_provided_via_robot
        elif self.is_vran_testline():
            platform = 'VRAN'
        else:
            user = 'toor4nsn' if user is None else user
            password = 'oZPS0POrRieRtu' if password is None else password
            ip = '192.168.255.1' if ip is None else ip
            command = 'sshpass -p {} ssh {}@{} "cat /proc/device-tree/module-identity/unit-id"'.format(password, user, ip)
            command = shlex.split(command)
            proc = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            stdout, stderr = proc.communicate()
            stdout = py3_string(stdout)
            stderr = py3_string(stderr)
            if stdout:
                platform = stdout.rstrip('\x00')
            else:
                raise Exception('Could not get gNB platform type via ssh')
        logging.getLogger('messaging.testenv').debug('Returned 5G platform type:\n{}'.format(platform))
        platform = str(platform).upper()
        print('Platform set to: {}'.format(platform))
        return platform

    def load_plugins(self):
        known_plugin_functions = load_classes_implemented_by_plugins(classes_group="PLUGIN_MESSAGE_SOURCES",
                                                                     logger=self.logger)
        for message_source_name, plug_messagesource_in_messaging in known_plugin_functions.items():
            try:
                plug_messagesource_in_messaging()
            # we intentionally catch all exceptions
            # since we don't want incorrect plugin to break whole ta_messaging
            except Exception as err:  # pylint: disable=broad-except
                self.logger.warning("Failed message source {} loading via {}, error: {!r}"
                                    .format(message_source_name,
                                            plug_messagesource_in_messaging, err))

    def validate_message_source_variant(self, network_elem_type, variant):
        """
        Validate if there is known construction-generator capable to build given variant of message-source
        :param network_elem_type: which NE we want message-source for? (UE, ENB, MME, ...)
        :param variant: tool-specific implementation of that message-source (wts, android, qualcomm, tshark,
        remote_tshark, ...)
        """
        available_variants = self.ne_factory.available_variants(element2create='message_source',
                                                                network_elem_type=network_elem_type)
        assert variant in available_variants,\
            "'{}' variant of '{}' not available. Available: {}"\
            .format(variant, network_elem_type, list(available_variants))

    def validate_variant_id(self, network_elem_type, variant, id_of_variant):
        """
        1) Validate correctness of tool-specific-id of NE
        2) Perform id conversion if possible (like: convert integer id from its string form to int: '7' --> 7)

        :param network_elem_type: which NE we want message-source for? (UE, ENB, MME, ...)
        :param variant: tool-specific implementation of that message-source (wts, android, qualcomm, tshark,
        remote_tshark, ...)
        :param id_of_variant: tool-specific-id to be validated/converted
        :return: valid id after conversion
        """
        validated_id_of_variant = self.ne_validator.validate(network_elem_type=network_elem_type,
                                                             variant=variant,
                                                             id_of_variant=id_of_variant)
        return validated_id_of_variant

    def create_msg_src_id(self, identifiers, network_elem_type, variant, specific_for_tool):
        """
        Create MsgSourceIdentification instance
        :param identifiers: iterable of pairs (id_type, identifier)
        :param network_elem_type: type of NE pointed by this identification
        :param specific_for_tool: (if given) name of tool that is using this id_type to identify NE
        :return: MsgSourceIdentification instance
        """
        return self.msg_src_id_factory.create_msg_src_id(identifiers, network_elem_type, variant, specific_for_tool)

    def get_message_source_construction_generator(self, network_elem_type, variant, id_of_variant):
        """
        Return generator that will return recipe 'how to build message-source' for requested NE variant with id_of_variant.
        Recipe is a pair (message-source-class-name, its-constructor-parameters)

        :param network_elem_type: which NE we want message-source for? (UE, ENB, MME, ...)
        :param variant: tool-specific implementation of that message-source (wts, android, qualcomm, tshark, remote_tshark, ...)
        :param id_of_variant: tool-specific-id of variant
        :return: iterator/generator returning pairs of (message-source-class-name, its-constructor-parameters)
        """
        # NetworkElementFactory.construction_recipe has no fixed 'id_of_network_element' parameter - it uses **construction_generator_kwargs
        # 'id_of_network_element' is a parameter-name-by-convention for building 'message_source'
        # so, each construction-generator registration for given variant should use that name as parameter name of registered construction_generator:
        #
        # def constructor_generator_for_msg_source_variant(id_of_network_element):
        #     tool_specific_id_of_ue = id_of_network_element
        #     yield 'message-source-class-to-instantiate', {'id': tool_specific_id_of_ue, other-class-constructor-parameters}
        #
        # self.ne_factory.register_construction(element2create='message_source', network_elem_type='UE', variant=variant2register,
        #                                       construction_generator=constructor_generator_for_msg_source_variant)

        construction_generator = self.ne_factory.construction_recipe(element2create='message_source',
                                                                     network_elem_type=network_elem_type,
                                                                     variant=variant,
                                                                     id_of_network_element=id_of_variant)
        return construction_generator

    def _register_available_message_sources(self):
        # CAUTION - convention:
        # Each construction-generator registration should use 'id_of_network_element' as parameter name of registered construction_generator:
        #
        # def constructor_generator_for_msg_source_variant(id_of_network_element):
        #     tool_specific_id_of_ue = id_of_network_element
        #     yield 'message-source-class-to-instantiate', {'id': tool_specific_id_of_ue, other-class-constructor-parameters}
        #
        # self.ne_factory.register_construction(element2create='message_source', network_elem_type='UE', variant=variant2register,
        #                                       construction_generator=constructor_generator_for_msg_source_variant)
        #
        # Thanks to that there will be possible abstract/uniform API to obtain message-source recipe via:
        #     NetworkElementFactory.construction_recipe(..., id_of_network_element=...)

        self._register_wts_id_validator()
        self._register_wts_message_sources()
        self._register_android_id_validator()
        self._register_android_message_sources()
        self._register_qualcomm_id_validator()
        self._register_qualcomm_message_sources()
        self._register_tshark_message_sources()
        self._register_remote_tshark_id_validator()
        self._register_remote_tshark_message_sources()
        self._register_ap_protocol_messages_source()

    def _register_wts_id_validator(self):
        """
        for testenv with WTS
        """
        def ensure_int_id(id_of_variant):
            wts_id = int(id_of_variant)  # wts uses id which is integer
            return wts_id

        def ensure_int_pair_id(id_of_variant):
            assert len(id_of_variant) == 2
            id_1 = id_of_variant[0]
            id_2 = id_of_variant[1]
            wts_id_1 = int(id_1)  # wts uses id which is integer
            wts_id_2 = int(id_2)  # wts uses id which is integer
            return [wts_id_1, wts_id_2]

        def ensure_int_dict_values(id_of_variant):
            assert isinstance(id_of_variant, dict)
            validated_dict = {}
            for key, value in list(id_of_variant.items()):
                validated_dict[key] = int(value)
                validated_dict[key] = str(value)  # TODO: just for now (backward compatibility)
            return validated_dict

        def ensure_id_is_none(id_of_variant):
            assert id_of_variant is None
            return None

        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='UE',
                                             variant='wts',
                                             validator_function=ensure_int_id)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='UE_GROUP',
                                             variant='wts',
                                             validator_function=ensure_int_pair_id)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='UE',
                                             variant='wts_5g',
                                             validator_function=ensure_int_id)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='UE',
                                             variant='wts_5g{}'.format(DYNAMIC_SOURCE_SUFFIX),
                                             validator_function=ensure_id_is_none)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='UE',
                                             variant='wts{}'.format(DYNAMIC_SOURCE_SUFFIX),
                                             validator_function=ensure_id_is_none)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='UE_GROUP',
                                             variant='wts_5g',
                                             validator_function=ensure_int_pair_id)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='ENB',
                                             variant='wts',
                                             validator_function=ensure_int_id)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='MME',
                                             variant='wts',
                                             validator_function=ensure_int_id)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='CELL',
                                             variant='wts',
                                             validator_function=ensure_int_dict_values)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='CELL',
                                             variant='wts_5g{}'.format(DYNAMIC_SOURCE_SUFFIX),
                                             validator_function=ensure_id_is_none)
        self.ne_validator.register_validator(name_of_element2validate='id_of_variant', network_elem_type='CELL',
                                             variant='wts{}'.format(DYNAMIC_SOURCE_SUFFIX),
                                             validator_function=ensure_id_is_none)

