    def _register_wts_message_sources(self):
        """
        for testenv with WTS
        """
        self._register_wts_iphy()
        self._register_wts_airphone()

        # ------------------------------------------------------------------- MME message-source
        def wts_mme_factory_recipe(id_of_network_element):
            wts_id_of_mme = int(id_of_network_element)
            ip = _get_mme_ip_by_wts_id(wts_id_of_mme)
            #              class to instantiate                                                    class constructor parameters
            yield 'ta_messaging.message_sources.message_sources_tshark_based.EPCSIMMessageSource', {'id': wts_id_of_mme,
                                                                                                    'ip': ip,
                                                                                                    'protocol': '(s1ap or m3ap or ngap)'}

        self.ne_factory.register_construction(element2create='message_source', network_elem_type='MME', variant='wts',
                                              construction_generator=wts_mme_factory_recipe)

        # ------------------------------------------------------------------- ENB message-source
        def wts_enb_factory_recipe(id_of_network_element):
            wts_id_of_enb = int(id_of_network_element)
            ip = _get_enb_ip_by_wts_id(wts_id_of_enb)
            protocol_filter = '(x2ap or f1ap or e1ap or sctp.data_payload_proto_id_nokia==50361 or sctp.data_payload_proto_id==61)'
            #              class to instantiate                                                    class constructor parameters
            yield 'ta_messaging.message_sources.message_sources_tshark_based.EPCSIMMessageSource', {'id': wts_id_of_enb,
                                                                                                    'ip': ip,
                                                                                                    'protocol': protocol_filter}

        self.ne_factory.register_construction(element2create='message_source', network_elem_type='ENB', variant='wts',
                                              construction_generator=wts_enb_factory_recipe)

    def _register_wts_iphy(self):
        """
        for testenv using rrc iphy
        """
        def os_env_selected_ue_msg_source_variant(id_of_network_element):
            iphy_id_of_ue = int(id_of_network_element)  # wts uses id which is integer
            if os.getenv('TSHARK', 'HEX').upper() == 'HEX':
                #              class to instantiate                                                     class constructor parameters
                yield 'ta_messaging.message_sources.message_sources_tshark_based.IPHYHexMessageSource', {'id': iphy_id_of_ue}
            else:
                yield 'ta_messaging.message_sources.message_sources_tshark_based.IPHYMessageSource', {'id': iphy_id_of_ue}

        self.ne_factory.register_construction(element2create='message_source', network_elem_type='UE', variant='wts',
                                              construction_generator=os_env_selected_ue_msg_source_variant)

        def iphy_global_message_source(id_of_network_element):
            yield 'ta_messaging.message_sources.message_sources_tshark_based.IPHYGlobalHexMessageSource', {}

        self.ne_factory.register_construction(element2create='message_source', network_elem_type='UE', variant='wts{}'.format(DYNAMIC_SOURCE_SUFFIX),
                                              construction_generator=iphy_global_message_source)

        # ------------------------------------------------------------------- UE_GROUP message-source
        def wts_ue_group_factory_recipe(id_of_network_element):
            iphy_ues_id_range = id_of_network_element
            #              class to instantiate                                                            class constructor parameters
            yield 'ta_messaging.message_sources.message_sources_tshark_based.IphyUeRangeHexMessageSource', {'id_range': iphy_ues_id_range}

        self.ne_factory.register_construction(element2create='message_source', network_elem_type='UE_GROUP', variant='wts',
                                              construction_generator=wts_ue_group_factory_recipe)

        # ------------------------------------------------------------------- CELL message-source
        def os_env_selected_cell_msg_source_variant(id_of_network_element):
            wts_cell_ident = id_of_network_element
            enb_id = wts_cell_ident['enb_id']
            cell_id = wts_cell_ident['cell_id']
            if os.getenv('TSHARK', 'HEX').upper() == 'HEX':
                #              class to instantiate                                                                       class constructor parameters
                yield 'ta_messaging.message_sources.message_sources_tshark_based.BroadcastMulticastIPHYHexMessageSource', {
                    'enb_id': enb_id,
                    'cell_id': cell_id}
            else:
                yield 'ta_messaging.message_sources.message_sources_tshark_based.BroadcastIPHYMessageSource', {
                    'enb_id': enb_id,
                    'cell_id': cell_id}
                yield 'ta_messaging.message_sources.message_sources_tshark_based.MulticastIPHYMessageSource', {
                    'enb_id': enb_id,
                    'cell_id': cell_id}

        self.ne_factory.register_construction(element2create='message_source', network_elem_type='CELL', variant='wts',
                                              construction_generator=os_env_selected_cell_msg_source_variant)

        def iphy_all_cells_message_source(id_of_network_element):
            yield 'ta_messaging.message_sources.message_sources_tshark_based.BroadcastIphyGlobalHexMessageSource', {}

        self.ne_factory.register_construction(element2create='message_source', network_elem_type='CELL',
                                              variant='wts{}'.format(DYNAMIC_SOURCE_SUFFIX),
                                              construction_generator=iphy_all_cells_message_source)

